package com.pulseim.conversation;
import com.pulseim.common.mq.GroupMemberChangedEvent; import org.springframework.amqp.rabbit.annotation.RabbitListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component class GroupMemberEventListener { private final ConversationRepository conversations; private final ConversationMemberRepository members; GroupMemberEventListener(ConversationRepository conversations,ConversationMemberRepository members){this.conversations=conversations;this.members=members;} @RabbitListener(queues="pulseim.conversation.group-members") @Transactional void handle(GroupMemberChangedEvent e){String cid="gc-"+e.groupId(); if("ADDED".equals(e.action())){ConversationEntity c=conversations.findById(cid).orElseGet(()->conversations.save(new ConversationEntity(cid,"GROUP",null,null,e.groupId(),java.time.Instant.now())));members.ensureMember(c.id(),e.userId());} else if("REMOVED".equals(e.action()))members.findByConversationIdAndUserId(cid,e.userId()).ifPresent(members::delete);}}